--- original/layout/theme.liquid
+++ edited/layout/theme.liquid
@@ -2,6 +2,10 @@
 <html class="no-touch supports-no-cookies" lang="{{ request.locale.iso_code }}">
   <head>
     {%- render 'head' -%}
+
+    {%- if template.name == 'index' -%}
+      {{ 'ta-vie-home.css' | asset_url | stylesheet_tag }}
+    {%- endif -%}

     {{ content_for_header }}
   </head>

--- original/assets/ta-vie-home.css
+++ edited/assets/ta-vie-home.css
@@ -0,0 +1,83 @@
+/*
+ * TA VIE home-page additions only.
+ * Keep Broadcast's fonts, editor-selected sizes and color schemes intact.
+ * Product cards and purchase controls retain their native styles.
+ * ID suffixes match the native sections created in templates/index.json.
+ */
+
+body.template-index #MainContent :is(
+  section[id$="ta_vie_intro"],
+  section[id$="ta_vie_story"],
+  section[id$="ta_vie_reading"]
+) .hero__title,
+body.template-index #MainContent section[id$="ta_vie_products"] .grid__heading,
+body.template-index #MainContent section[id$="ta_vie_blog"] .blog__title {
+  line-height: 1.65;
+  letter-spacing: 0.04em;
+  overflow-wrap: anywhere;
+}
+
+body.template-index #MainContent :is(
+  section[id$="ta_vie_intro"],
+  section[id$="ta_vie_story"],
+  section[id$="ta_vie_reading"]
+) .hero__rte,
+body.template-index #MainContent section[id$="ta_vie_products"] .grid__description {
+  line-height: 1.9;
+  letter-spacing: 0.015em;
+  overflow-wrap: anywhere;
+}
+
+body.template-index #MainContent :is(
+  section[id$="ta_vie_intro"],
+  section[id$="ta_vie_story"],
+  section[id$="ta_vie_reading"]
+) .hero__rte p,
+body.template-index #MainContent section[id$="ta_vie_products"] .grid__description p {
+  line-height: inherit;
+}
+
+/*
+ * These editorial sections should remain readable if the theme's animation
+ * script has not run. The product-grid override covers its heading only.
+ */
+body.template-index #MainContent :is(
+  section[id$="ta_vie_intro"],
+  section[id$="ta_vie_story"],
+  section[id$="ta_vie_reading"],
+  section[id$="ta_vie_blog"]
+) [data-aos],
+body.template-index #MainContent section[id$="ta_vie_products"] .grid__heading-holder [data-aos] {
+  opacity: 1;
+  visibility: visible;
+  transform: none;
+  animation: none;
+  transition: none;
+}
+
+@media only screen and (max-width: 749px) {
+  /* Honor the native 1/2-column mobile selection on wide phones as well. */
+  body.template-index #MainContent section[id$="ta_vie_products"] .grid--mobile-vertical {
+    --columns: var(--COLUMNS-MOBILE);
+  }
+
+  body.template-index #MainContent :is(
+    section[id$="ta_vie_intro"],
+    section[id$="ta_vie_story"],
+    section[id$="ta_vie_products"],
+    section[id$="ta_vie_reading"],
+    section[id$="ta_vie_blog"]
+  ) {
+    --padding-top: min(32px, calc(var(--PT, 48px) * 0.6));
+    --padding-bottom: min(36px, calc(var(--PB, 48px) * 0.6));
+    --PT-MOBILE: var(--padding-top);
+  }
+
+  body.template-index #MainContent :is(
+    section[id$="ta_vie_intro"],
+    section[id$="ta_vie_story"],
+    section[id$="ta_vie_reading"]
+  ) .hero__content__wrapper {
+    padding-inline: 20px;
+  }
+}
